    H=len(g);W=len(g[0]); res=[row[:] for row in g]
    for r in range(H):
        nz=[(c,g[r][c]) for c in range(W) if g[r][c]!=0]
        if not nz: continue
        # find minimal period
        vals=[v for _,v in nz]; cs=[c for c,_ in nz]
        per=None
        for p in range(1,W+1):
            if sum(abs(v2-v1)-p*(c2-c1) if False else 0 for c1,v1,c2,v2 in zip(*[]) )>=0: pass
        break
    return res
# alternative: global rule. Check demo: is out just inp with 0s replaced so that rows satisfy periodic continuation?
# Look at row patterns of input vs output directly per row, compare to simple cyclic completion using first nonzero segment.
ok=all(True for r in range(H))
for r in range(min(4,H)):
    i_=[]; o_=[]
    for c in range(W):
        v=inp[r][c]; u=outp[r][c]
        if v==0: i_.append(None); o_.append(u)
        else: i_.append(v)
    print(r, ''.join(str(v) for v in i_), ''.join(str(v) for v in o_))

